// 1. 密封接口配合 Record：适合有限领域模型
public sealed interface Shape permits Circle, Rectangle, Triangle {}

public record Circle(double radius) implements Shape {}
public record Rectangle(double width, double height) implements Shape {}
public final class Triangle implements Shape {
    private final double a, b, c;
    public Triangle(double a, double b, double c) {
        this.a = a; this.b = b; this.c = c;
    }
}

// 2. 子类型选择 final / sealed / non-sealed
public sealed interface PaymentMethod permits CreditCard, Wallet, BankTransfer {}
public record CreditCard(String cardNumber) implements PaymentMethod {}
public sealed interface Wallet extends PaymentMethod permits Alipay, WeChatPay {}
public record Alipay(String account) implements Wallet {}
public record WeChatPay(String openId) implements Wallet {}
public non-sealed class BankTransfer implements PaymentMethod {
    private final String bankAccount;
    public BankTransfer(String bankAccount) { this.bankAccount = bankAccount; }
}

// 3. 配合 switch 模式匹配（Java 21）
String describe(Shape shape) {
    return switch (shape) {
        case Circle c -> "圆，半径=" + c.radius();
        case Rectangle r -> "矩形，宽=" + r.width() + " 高=" + r.height();
        case Triangle t -> "三角形";
    };
}
